node --input-type=module <<'NODE'
import fs from 'node:fs';
const plan=JSON.parse(fs.readFileSync('shift-plan.json','utf8'));
const limits=[80,40,50,70];
const actual=plan.acKw.map((p,i)=>Math.min(p,limits[i]));
for (const eta of [0.9,0.85]) {
  const a=72+0.5*eta*(actual[0]+actual[1]);
  const b=76+0.5*eta*(actual[2]+actual[3]);
  console.log(JSON.stringify({eta,actual,departureKwh:[+a.toFixed(6),+b.toFixed(6)],margins:[+(a-126).toFixed(6),+(b-130).toFixed(6)],bothRelease:a>=126-1e-9&&b>=130-1e-9}));
}
